// src/main/java/com/example/account/strategy/DoctorAccountStrategy.java
@Service
public class DoctorAccountStrategy implements AccountStrategy {

    private final DoctorRepository doctorRepository;

    public DoctorAccountStrategy(DoctorRepository doctorRepository) {
        this.doctorRepository = doctorRepository;
    }

    @Override
    public <T> T findById(Object id, Class<T> type) {
        // Safe casting because we control the implementation context
        return (T) doctorRepository.findById((Integer) id)
                .orElseThrow(() -> new EntityNotFoundException("Doctor not found"));
    }

    @Override
    public <T> T findByPhone(String phone, Class<T> type) {
        // Implement the specific phone finder for DoctorAccount
        return (T) doctorRepository.findByPhone(phone) // Assuming you add findByPhone to DoctorRepository
                .orElseThrow(() -> new EntityNotFoundException("Doctor not found by phone"));
    }
}

