    DOCTOR, USER
}

public record AccountDetails(
        Integer id, String phone, String fullName, AccountType type) {}

public interface AccountLookupStrategy {
    AccountType type();
    AccountDetails findById(Integer id);
}
```

Each strategy uses its own Spring Data repository and maps the entity to the common result:

```java
@Service
public class DoctorLookupStrategy implements AccountLookupStrategy {
    private final DoctorAccountRepository repository;

    public DoctorLookupStrategy(DoctorAccountRepository repository) {
        this.repository = repository;
    }

    @Override
    public AccountType type() {
        return AccountType.DOCTOR;
    }

    @Override
    public AccountDetails findById(Integer id) {
        DoctorAccount account = repository.findById(id)
                .orElseThrow(() -> new EntityNotFoundException("Doctor not found"));

        return new AccountDetails(
                account.getId(), account.getPhone(),
                account.getFullName(), AccountType.DOCTOR);
    }
}
```

Create an equivalent `UserLookupStrategy`, then have the service build a map from the strategies Spring injects:

```java
@Service
public class AccountService {
    private final Map<AccountType, AccountLookupStrategy> strategies;

    public AccountService(List<AccountLookupStrategy> lookupStrategies) {
        this.strategies = lookupStrategies.stream()
                .collect(Collectors.toMap(
                        AccountLookupStrategy::type, Function.identity()));
    }

    public AccountDetails getById(AccountType type, Integer id) {
        AccountLookupStrategy strategy = strategies.get(type);
        if (strategy == null) {
            throw new IllegalArgumentException("Unsupported account type: " + type);
        }
        return strategy.findById(id);
    }
}
```

This keeps repository-specific lookup logic separate. To add another type, add its entity, repository, and strategy. If all account types are really one domain concept and should share identity and lifecycle, consider a common account model or JPA inheritance instead.

